import System.FormatException;import System.ReadOnlySpan;import System.Globalization.NumberStyles;import System.Exception;import System.ArgumentException;import System.ArgumentOutOfRangeException;import System.Globalization.NumberFormatInfo;import System.Type;import System.Decimal;import System.IComparable;import System.IFormattable;import System.IFormatProvider;import System.InvalidOperationException;import java.nio.file.*;import java.util.*;
class DecimalParseProviderBoundariesProbe {
 interface Action{void run();}
 static String units(String s){if(s==null)return "~";StringJoiner j=new StringJoiner(",");for(char c:s.toCharArray())j.add(Integer.toString(c));return j.toString();}
 static String text(String s){if(s.equals("~"))return null;StringBuilder b=new StringBuilder();if(!s.isEmpty())for(String u:s.split(","))b.append((char)Integer.parseInt(u));return b.toString();}
 static int[] sizes(String s){if(s.equals("~"))return null;if(s.isEmpty())return new int[0];String[] p=s.split(",");int[] a=new int[p.length];for(int i=0;i<a.length;i++)a[i]=Integer.parseInt(p[i]);return a;}
 static String csv(int[] a){StringJoiner j=new StringJoiner(",");for(int v:a)j.add(Integer.toString(v));return j.toString();}
 static String outcome(Action a){try{a.run();return "OK";}catch(Exception e){return String.join("|","ERR",e.getClass().getName(),units(e.get_Message()),Integer.toString(e.get_HResult()),units(e instanceof ArgumentException x?x.get_ParamName():null),e instanceof ArgumentOutOfRangeException x&&x.get_ActualValue()!=null?x.get_ActualValue().toString():"~");}}
 static void check(String a,String e,String c){if(!a.equals(e))throw new AssertionError(c+" actual="+a+" expected="+e);}
 static String flag(boolean b){return b?"1":"0";}
 static NumberFormatInfo custom(){NumberFormatInfo n=new NumberFormatInfo();n.set_NegativeSign("~");n.set_PositiveSign("^");n.set_NumberDecimalSeparator("@");n.set_NumberGroupSeparator("_");n.set_NumberGroupSizes(new int[]{2,3});n.set_CurrencySymbol("USD");n.set_CurrencyDecimalSeparator(":");n.set_CurrencyGroupSeparator("'");n.set_CurrencyGroupSizes(new int[]{3,2});n.set_CurrencyPositivePattern(2);n.set_CurrencyNegativePattern(14);n.set_NumberNegativePattern(4);n.set_PercentSymbol("%!");return n;}
 static String compare(IComparable value,Object other){try{return "OK|"+value.CompareTo(other);}catch(Exception e){return error(e);}}
 static String format(IFormattable value,String f,IFormatProvider provider){try{return "OK|"+units(value.ToString(f,provider));}catch(Exception e){return error(e);}}
 static String error(Exception e){return String.join("|","ERR",e.getClass().getName(),units(e.get_Message()),Integer.toString(e.get_HResult()),units(e instanceof ArgumentException x?x.get_ParamName():null),"~");}
 static final class Actor implements IFormatProvider{int calls;Type last;Object result;Exception failure;Actor(String profile){if(profile.equals("wrong"))result="wrong";if(profile.equals("custom")){NumberFormatInfo n=new NumberFormatInfo();n.set_NumberDecimalSeparator("@");result=n;}if(profile.equals("throwing"))failure=new InvalidOperationException("provider failure");if(profile.equals("format-throwing"))failure=new FormatException("provider format failure");}public Object GetFormat(Type type){calls++;last=type;if(failure!=null)throw failure;return result;}}
 static String reduced(Exception e){return "ERR|"+e.getClass().getName()+"|"+e.get_HResult()+"|"+units(e instanceof ArgumentException x?x.get_ParamName():null);}
 public static void main(String[] args)throws java.lang.Exception{int groups=0,calls=0;for(String line:Files.readAllLines(Path.of(args[0]))){String[] p=line.split("\t",-1);int style=Integer.parseInt(p[0]);String input=text(p[1]);Actor actor=new Actor(p[2]);boolean chars=p[3].equals("chars"),trying=p[4].equals("1");Decimal[] holder={new Decimal(123)};String actual;Exception thrown=null;try{Decimal value=null;boolean result=false;if(chars){char[] backing=("BAD"+(input==null?"":input)+"BAD").toCharArray();ReadOnlySpan<Character> span=ReadOnlySpan.OfChars(backing,3,backing.length-6);if(trying)result=Decimal.TryParse(span,NumberStyles.FromInt32(style),actor,holder);else value=Decimal.Parse(span,NumberStyles.FromInt32(style),actor);}else if(trying)result=Decimal.TryParse(input,NumberStyles.FromInt32(style),actor,holder);else value=Decimal.Parse(input,NumberStyles.FromInt32(style),actor);actual=trying?"OK|"+flag(result):"OK|"+csv(Decimal.GetBits(value));}catch(Exception e){thrown=e;actual=reduced(e);}check(actual,p[5],line);check(csv(Decimal.GetBits(holder[0])),p[6],"result "+line);check(Integer.toString(actor.calls),p[7],"callback count");check(flag(actor.last==Type.GetType("System.Globalization.NumberFormatInfo")),p[8],"requested type");boolean same=actor.failure!=null&&thrown==actor.failure;check(flag(same),p[9],"exception identity");if(same)check(units(thrown.get_Message()),p[10],"provider message");groups+=5;calls++;}java.lang.System.out.println("PASS Decimal parse provider calls="+calls+" groups="+groups);}}
